SELECT 
FROM HR_EMPLOYEE H
WHERE H.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
  AND H.EMPID = #{empid, jdbcType=VARCHAR}
  AND ROWNUM = 1

SELECT F.FILE_NO, F.APPLY_NO, F.APPLY_TYPE, F.FILE_NAME FROM ESS_FILE F WHERE F.APPLY_TYPE = #{applyType, jdbcType=VARCHAR} AND F.ACTIVITY = 1 AND F.APPLY_NO IN
#{no, jdbcType=VARCHAR}
ORDER BY F.APPLY_NO, F.CREATE_DATE

mapper.update:
UPDATE ESS_FILE
   SET ACTIVITY = 0,
       UPDATE_DATE = SYSDATE,
       UPDATED_BY = #{adminID, jdbcType=VARCHAR}
 WHERE FILE_NO = #{fileNo, jdbcType=VARCHAR}

UPDATE ESS_FILE
   SET ACTIVITY = 0,
       UPDATE_DATE = SYSDATE,
       UPDATED_BY = #{adminID, jdbcType=VARCHAR}
 WHERE APPLY_TYPE = #{applyType, jdbcType=VARCHAR}
   AND APPLY_NO = #{applyNo, jdbcType=VARCHAR}
   AND ACTIVITY = 1
